def clean_amount(text):
    cleaned = text.replace("$", "").replace(",", "").strip()
    try:
        return round(float(cleaned) * 100)
    except ValueError:
        return None

for t in ["$1,250.00", "19.90", "abc"]:
    print(clean_amount(t))

def dedupe_latest(rows):
    latest = {}
    for row in rows:
        key = row["order_id"]
        if key not in latest or row["updated_at"] >= latest[key]["updated_at"]:
            latest[key] = row
    return [latest[key] for key in sorted(latest)]

rows = [{"order_id": 3, "status": "paid", "updated_at": "2025-03-02"}, {"order_id": 1, "status": "paid", "updated_at": "2025-03-01"}, {"order_id": 3, "status": "refunded", "updated_at": "2025-03-03"}]
print([(r["order_id"], r["status"]) for r in dedupe_latest(rows)])
